  if (normalized.states() != fcitx::KeyStates()) {
    return false;
  }

  const std::string utf8 = fcitx::Key::keySymToUTF8(normalized.sym());
  if (utf8.empty()) {
    return false;
  }

  for (unsigned char ch : utf8) {
    if (ch < 0x20 || ch == 0x7f) {
      return false;
    }
  }
  return true;
